          kGroupDataXBorder + r.x0() - block_rect.x0() * kBlockDim,
          kGroupDataYBorder + r.y0() - block_rect.y0() * kBlockDim, r.xsize(),
          r.ysize());
      JXL_RETURN_IF_ERROR(FinalizeImageRect(group_data, group_data_rect, {},
                                            dec_state, thread, decoded, r));
    }
  }
